package rules_test

// Function-level parity with the Python helpers. testdata/functions.json is
// generated by running scripts/gitguard (parse_remote, is_local_url,
// is_gh_helper, ssh_command_problems, cleanup, check, body_section_problems,
// pr_target_problem) on the same inputs.

import (
	"encoding/json"
	"os"
	"path/filepath"
	"reflect"
	"sort"
	"testing"

	"github.com/nnminh-sam/agentic-workflows/plugins/my-git/cli/defaults"
	"github.com/nnminh-sam/agentic-workflows/plugins/my-git/cli/internal/config"
	"github.com/nnminh-sam/agentic-workflows/plugins/my-git/cli/internal/policy"
	"github.com/nnminh-sam/agentic-workflows/plugins/my-git/cli/internal/rules"
	"github.com/nnminh-sam/agentic-workflows/plugins/my-git/cli/internal/verdict"
)

func testProfile() map[string]any {
	return map[string]any{
		"github_user": "octocat",
		"github_orgs": []any{"octo-org"},
		"git_name":    "octocat",
		"git_email":   []any{"123+octocat@users.noreply.github.com"},
		"ssh_key":     "keys/gh/id_ed25519",
	}
}

func testPolicy(t testing.TB, vars map[string]any) *policy.Policy {
	t.Helper()
	cs, err := config.LoadContracts(defaults.FS)
	if err != nil {
		t.Fatal(err)
	}
	for _, c := range cs {
		for i := range c.Rules {
			c.Rules[i].Params = policy.SubstituteParams(c.Rules[i].Params, vars)
		}
	}
	return &policy.Policy{Contracts: cs, Vars: vars}
}

func ruleIDs(v verdict.Verdict) []string {
	seen := map[string]bool{}
	out := []string{}
	for _, f := range v.Findings {
		if !seen[f.RuleID] {
			seen[f.RuleID] = true
			out = append(out, f.RuleID)
		}
	}
	sort.Strings(out)
	return out
}

type functionsFixture struct {
	ParseRemote []struct{ URL, Kind, Host, Owner string } `json:"parse_remote"`
	IsLocalURL  []struct {
		URL   string `json:"url"`
		Local bool   `json:"local"`
	} `json:"is_local_url"`
	IsGhHelper []struct {
		Helper string `json:"helper"`
		GH     bool   `json:"gh"`
	} `json:"is_gh_helper"`
	SSHProblems []struct {
		Cmd, Key string
		N        int
	} `json:"ssh_problems"`
	Cleanup []struct {
		In  string `json:"in"`
		Out string `json:"out"`
	} `json:"cleanup"`
	CheckMessage []struct {
		Msg                string           `json:"msg"`
		Decision           verdict.Decision `json:"decision"`
		Rules              []string         `json:"rules"`
		HeaderWarnDecision verdict.Decision `json:"header_warn_decision"`
		HeaderRules        []string         `json:"header_rules"`
	} `json:"check_message"`
	BodySections []struct {
		Body     string   `json:"body"`
		Problems []string `json:"problems"`
	} `json:"body_sections"`
	PRTarget []struct {
		Base, Head string
		Problem    bool
	} `json:"pr_target"`
}

func loadFunctions(t *testing.T) functionsFixture {
	t.Helper()
	data, err := os.ReadFile(filepath.Join("testdata", "functions.json"))
	if err != nil {
		t.Fatal(err)
	}
	var fx functionsFixture
	if err := json.Unmarshal(data, &fx); err != nil {
		t.Fatal(err)
	}
	return fx
}

func TestPythonParityFunctions(t *testing.T) {
	fx := loadFunctions(t)
	pol := testPolicy(t, testProfile())
	t.Run("parse_remote", func(t *testing.T) {
		for _, c := range fx.ParseRemote {
			k, h, o := rules.ParseRemote(c.URL)
			if k != c.Kind || h != c.Host || o != c.Owner {
				t.Errorf("%q: got (%s,%s,%s) want (%s,%s,%s)", c.URL, k, h, o, c.Kind, c.Host, c.Owner)
			}
		}
	})
	t.Run("is_local_url", func(t *testing.T) {
		for _, c := range fx.IsLocalURL {
			if got := rules.IsLocalURL(c.URL); got != c.Local {
				t.Errorf("%q: got %v want %v", c.URL, got, c.Local)
			}
		}
	})
	t.Run("is_gh_helper", func(t *testing.T) { // test_identity.test_gh_helper_spellings
		for _, c := range fx.IsGhHelper {
			if got := rules.IsGhHelper(c.Helper); got != c.GH {
				t.Errorf("%q: got %v want %v", c.Helper, got, c.GH)
			}
		}
	})
	t.Run("ssh_command_problems", func(t *testing.T) { // test_identity.test_ssh_option_spellings
		for _, c := range fx.SSHProblems {
			got := rules.SSHCommandProblems(c.Cmd, c.Key, []string{"IdentitiesOnly=yes"}, "")
			if len(got) != c.N {
				t.Errorf("%q key %q: %d problems %q, want %d", c.Cmd, c.Key, len(got), got, c.N)
			}
		}
	})
	t.Run("cleanup", func(t *testing.T) {
		for _, c := range fx.Cleanup {
			if got := rules.Cleanup(c.In); got != c.Out {
				t.Errorf("%q: got %q want %q", c.In, got, c.Out)
			}
		}
	})
	t.Run("check_message", func(t *testing.T) {
		commit := pol.Contract(policy.Commit)
		for _, c := range fx.CheckMessage {
			v := rules.CheckMessage(c.Msg, commit)
			if v.Decision() != c.Decision || !reflect.DeepEqual(ruleIDs(v), c.Rules) {
				t.Errorf("CheckMessage %q: got %s %v want %s %v", c.Msg, v.Decision(), ruleIDs(v), c.Decision, c.Rules)
			}
			h := rules.CheckHeader(c.Msg, commit, verdict.Warn)
			if h.Decision() != c.HeaderWarnDecision || !reflect.DeepEqual(ruleIDs(h), c.HeaderRules) {
				t.Errorf("CheckHeader %q: got %s %v want %s %v", c.Msg, h.Decision(), ruleIDs(h), c.HeaderWarnDecision, c.HeaderRules)
			}
		}
	})
	t.Run("body_section_problems", func(t *testing.T) {
		params := pol.Contract(policy.GitHubCLI).Rule("GH008").Params
		for _, c := range fx.BodySections {
			got := rules.BodySectionProblems(c.Body, params)
			want := c.Problems
			if len(got) == 0 && len(want) == 0 {
				continue
			}
			if !reflect.DeepEqual(got, want) {
				t.Errorf("%q:\n got %q\nwant %q", c.Body, got, want)
			}
		}
	})
	t.Run("pr_target_problem", func(t *testing.T) {
		br := pol.Contract(policy.Branching)
		for _, c := range fx.PRTarget {
			if got := rules.PRTargetProblem(c.Base, c.Head, br) != ""; got != c.Problem {
				t.Errorf("base %q head %q: problem=%v want %v", c.Base, c.Head, got, c.Problem)
			}
		}
	})
}
